<?php
// Table renderers keep repetitive row controls out of the workspace.
function item_table(array $items,string $empty='No items in this view.'):void { ?>
<div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Item</th><th>Location</th><th>Status</th><th>Reported</th><th class="action-column">Actions</th></tr></thead><tbody><?php foreach($items as $item): $status=$item['status']==='claimed' ? 'claimed' : $item['moderation_status']; ?><tr><td><button class="table-item-button" data-review="item" data-id="<?= (int)$item['id'] ?>"><img src="<?= e(image_url($item['image_path'])) ?>" alt="" loading="lazy"><span><strong class="truncate" title="<?= e($item['title']) ?>"><?= e($item['title']) ?></strong><small><?= e($item['category']) ?> &middot; <?= e(ucfirst($item['status'])) ?></small></span></button></td><td><span class="truncate location-cell" title="<?= e($item['location']) ?>"><?= e($item['location']) ?></span></td><td><span class="admin-pill <?= e($status) ?>"><?= e(ucfirst($status)) ?></span></td><td class="date-cell"><?= e(date('M j, Y',strtotime($item['created_at']))) ?></td><td><details class="row-menu"><summary aria-label="Actions for <?= e($item['title']) ?>">&#8943;</summary><div><button data-review="item" data-id="<?= (int)$item['id'] ?>">View &amp; review</button><a href="public/edit.php?id=<?= (int)$item['id'] ?>">Edit item</a><?php if($item['moderation_status']==='pending'): ?><button data-review="item" data-id="<?= (int)$item['id'] ?>">Approve / reject</button><?php endif ?><?php if($item['moderation_status']!=='archived'): ?><button data-confirm-action="archive" data-id="<?= (int)$item['id'] ?>" data-title="<?= e($item['title']) ?>">Archive item</button><?php endif ?></div></details></td></tr><?php endforeach ?><?php if(!$items): ?><tr><td class="admin-empty" colspan="5"><span aria-hidden="true">&#10003;</span><strong><?= e($empty) ?></strong><small>New activity will appear here.</small></td></tr><?php endif ?></tbody></table></div>
<?php }
function claim_table(array $claims):void { ?>
<div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Item</th><th>Claimant</th><th>Status</th><th>Submitted</th><th class="action-column">Actions</th></tr></thead><tbody><?php foreach($claims as $claim): ?><tr><td><button class="table-item-button" data-review="claim" data-id="<?= (int)$claim['id'] ?>"><span><strong class="truncate" title="<?= e($claim['title']) ?>"><?= e($claim['title']) ?></strong><small>Request #<?= (int)$claim['id'] ?></small></span></button></td><td><span class="truncate location-cell" title="<?= e($claim['name']) ?>"><?= e($claim['name']) ?></span></td><td><span class="admin-pill <?= e($claim['status']==='resolved' ? 'claimed' : $claim['status']) ?>"><?= $claim['status']==='resolved' ? 'Approved' : e(ucfirst($claim['status'])) ?></span></td><td class="date-cell"><?= e(date('M j, Y',strtotime($claim['created_at']))) ?></td><td><details class="row-menu"><summary aria-label="Actions for claim #<?= (int)$claim['id'] ?>">&#8943;</summary><div><button data-review="claim" data-id="<?= (int)$claim['id'] ?>">Review claim</button><button data-review="item" data-id="<?= (int)$claim['item_id'] ?>">View item</button></div></details></td></tr><?php endforeach ?><?php if(!$claims): ?><tr><td class="admin-empty" colspan="5"><span aria-hidden="true">&#10003;</span><strong>No claims in this view.</strong><small>New recovery requests will appear here.</small></td></tr><?php endif ?></tbody></table></div>
<?php }
